PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "role" varchar not null default 'reception');
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "bookings" ("id" integer primary key autoincrement not null, "room_id" integer not null, "customer_name" varchar not null, "email" varchar not null, "phone" varchar, "check_in" date not null, "check_out" date not null, "status" varchar not null default 'pending', "message" text, "created_at" datetime, "updated_at" datetime, "guests" integer not null default '1', "country" varchar, foreign key("room_id") references "rooms"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "galleries" ("id" integer primary key autoincrement not null, "title_es" varchar, "title_en" varchar, "image_path" varchar not null, "order" integer not null default '0', "created_at" datetime, "updated_at" datetime, "show_in_carousel" tinyint(1) not null default '0', "carousel_order" integer not null default '0');
CREATE TABLE IF NOT EXISTS "rooms" ("id" integer primary key autoincrement not null, "name_es" varchar not null, "name_en" varchar not null, "description_es" text, "description_en" text, "price" numeric not null, "capacity" integer not null, "status" varchar not null default 'active', "amenities" text, "image" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" text, "type" varchar not null default 'text', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "attractions" ("id" integer primary key autoincrement not null, "title_es" varchar not null, "title_en" varchar not null, "description_es" text not null, "description_en" text not null, "image_path" varchar, "order" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "gallery_room" ("id" integer primary key autoincrement not null, "gallery_id" integer not null, "room_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("gallery_id") references "galleries"("id") on delete cascade, foreign key("room_id") references "rooms"("id") on delete cascade);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "settings_key_unique" on "settings" ("key");
COMMIT;
