INSERT INTO rooms VALUES(1,'Habitación Doble Deluxe','Standard Deluxe Double Room','Esta habitación doble es amplia y cuenta con artículos de aseo gratuitos y baño privado con ducha. Dispone de aire acondicionado, armario, caja fuerte, suelo de baldosa. Dispone de 2 camas.','Providing free toiletries, this double room includes a private bathroom with a shower. The spacious double room provides air conditioning, a wardrobe, a safe deposit box, a tiled floor. The unit offers 2 beds.',50,4,'active','["WiFi","TV"]','/storage/gallery/oprUj3cLHAFhny4BeCS2vg3eAm5DhgjH8vI5ueLu.webp','2026-01-22 22:36:20','2026-01-24 07:54:12');
INSERT INTO rooms VALUES(2,'Habitación Deluxe con cama extragrande','Deluxe Room with King Bed','Los huéspedes disfrutarán de una experiencia especial, ya que la habitación doble cuenta con bañera de hidromasaje. Incluye artículos de aseo gratuitos y baño privado con bañera. La espaciosa habitación doble cuenta con aire acondicionado, armario, caja fuerte y suelo de baldosa. El alojamiento cuenta con 1 cama.','Guests will have a special experience as the double room features a hot tub. Providing free toiletries, this double room includes a private bathroom with a bath. The spacious air-conditioned double room, a wardrobe, a safe deposit box and a tiled floor. The unit offers 1 bed.',55,2,'active','["WiFi","TV"]','/storage/gallery/9tLJRDNZF6VZJiAvnpVdjZBqzDLXlT5G5xYcj0yG.webp','2026-01-22 22:36:20','2026-01-24 07:54:20');
