INSERT INTO attractions VALUES(1,'Centro de Visitantes de Agua Clara','Centro de Visitantes de Agua Clara','<p>El Centro de Visitantes de Agua Clara, en la provincia de Colón.</p>','<p>The Agua Clara Visitor Center, in the province of Colón.</p>','/storage/attractions/WOBJ12P5WBZBpiGUxpK9TSLUpakHaHSIigFuPEnp.webp',1,'2026-01-23 01:41:45','2026-01-23 20:41:04');
INSERT INTO attractions VALUES(2,'Zona Libre de Colón','Colon Free Zone','<p>El centro logístico y comercial más grande de la región.</p>','<p>The largest commercial and logistics center in the region.</p>','/storage/attractions/2otNiMh5TXVzmxoDIFSZdm8eiOinUcIqV6e8DNrT.webp',2,'2026-01-23 01:41:45','2026-01-23 20:41:37');
INSERT INTO attractions VALUES(3,'Playas','Beaches','<p>Aguas cristalinas y ambiente caribeño a pocos minutos.</p>','<p>Crystal clear waters and Caribbean atmosphere just minutes away.</p>','/storage/gallery/ExOQYUhOj4uZ7OQoue7BjdT6Jr55q9iGTlYm71ra.webp',3,'2026-01-23 01:41:45','2026-01-24 14:34:01');
INSERT INTO attractions VALUES(4,'Fuerte San Lorenzo','Fort San Lorenzo','<p>Patrimonio de la Humanidad por la UNESCO con vista al Río Chagres</p>','<p>UNESCO World Heritage Site overlooking the Chagres River</p>','/storage/gallery/Bu24wohnEQ2s1oYUJJag6qJPLaBmnsALYViMVuFi.webp',0,'2026-01-23 20:21:52','2026-01-23 20:37:48');
INSERT INTO attractions VALUES(7,'Puerto Colón 2000','Port Colon 2000','<p>Embárcate en una aventura inolvidable hacia el puerto de cruceros de Colón, Panamá</p>','<p>Embark on an unforgettable adventure to the cruise port of Colón, Panama</p>','/storage/attractions/LCMzhsvfcRGTGCZGzeZcR9jFYWo6qikqBfgIU0QU.webp',0,'2026-01-23 21:09:02','2026-01-23 21:09:02');
INSERT INTO attractions VALUES(8,'Ferrocarril Transístmico del Canal de Panamá','Panama Canal Trans-Isthmian Railway','<p>2.5 horas - Un recorrido guiado inolvidable de la selva y el canal en el ferrocarril transístmico de Panamá. Viaje en tren por la ruta del Canal de Panama.</p>','<p>2.5 hours - An unforgettable guided tour of the jungle and the canal on the Panama Transisthmian Railway. Train journey along the Panama Canal route.</p>','/storage/attractions/sttPE8SiceYxJAobo7nYxgaizs3VV0ZhbAjraUcd.webp',0,'2026-01-23 21:11:13','2026-01-23 21:11:13');
